+let capture = null;
+globalThis.document = { createElement: () => ({
+  getContext: () => ({
+    createImageData: (w, h) => ({ data: new Uint8ClampedArray(w * h * 4) }),
+    putImageData: ({ data }) => capture?.push(data.slice()),
+  }),
+}) };
+const ctx = { save() {}, restore() {}, drawImage() {} };
+const opaque = (x, y) => x === -7 || (x === 8 && y > 1);
+const interiorKeys = new Set(["0,0", "1,0", "1,1"]);
+const isShelterInterior = (x, y) => interiorKeys.has(\`\${x},\${y}\`);
+function box(x, y) {
+  return [[{x, y}, {x: x + 4, y}, {x: x + 4, y: y + 4}, {x, y: y + 4}]];
+}
+const regions = [{ family: "lava", loops: box(-5, -5) }, { family: "water", loops: box(4, 4) }];
+function draw(engine, frame, options = {}) {
+  const { sheltered = false, terrain = [], ambient = null, offset = 0 } = options;
+  const lights = [{ x: 2, y: 2, radius: 8, flicker: 1 + 0.1 * Math.sin(frame * 0.2) }];
+  engine.render(ctx, lights, opaque, -16 + offset, -11, 16 + offset, 11, ambient, 210,
+    ambient ? (x, y) => x < 3 && y < 4 : null, null, terrain, frame / 60, 1,
+    { playerSheltered: sheltered, isShelterInterior });
+}
+function compare(create) {
+  const engine = create();
+  capture = [];
+  const open = { terrain: regions, ambient: [0.4, 0.5, 0.6] };
+  draw(engine, 0, open);
+  draw(engine, 1, { ...open, sheltered: true });
+  engine.setFloorNoise(0.4, 0.2);
+  draw(engine, 2, { ...open, sheltered: true });
+  draw(engine, 3, { ...open, offset: 1 });
+  engine.clearFloorRelief();
+  draw(engine, 4, open);
+  const buffers = capture;
+  capture = null;
+  return buffers;
+}
